// "Talk to the author" from a blog post on guyshore.com.
// The site posts JSON; n8n nests it under body for webhook calls.
const raw = $input.first().json;
const b = raw.body ?? raw;
const str = (v, max = 5000) => (v ?? '').toString().trim().slice(0, max);
const esc = (s) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

const lang = str(b.lang) === 'pt' ? 'pt' : 'en';
const name = str(b.name, 120);
const email = str(b.email, 200);
const message = str(b.message);
const articleTitle = str(b.articleTitle, 300);
const rawUrl = str(b.articleUrl, 300);
// Only ever link back to this site.
const articleUrl = rawUrl.startsWith('https://guyshore.com/') ? rawUrl : 'https://guyshore.com/blog';
const newsletter = b.newsletter === true || b.newsletter === 'true';
const position = str(b.position, 20) || 'unknown';
const valid = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email) && message.length > 0 && name.length > 0;

const ink = '#18181b', steel = '#3f3f46', slate = '#6b6b74', mist = '#f4f4f5', line = '#e4e4e7';
const font = "-apple-system, BlinkMacSystemFont, 'Segoe UI', Helvetica, Arial, sans-serif";
const msgHtml = esc(message).replace(/\n/g, '<br>');

const shell = (preheader, inner) => '<!doctype html><html><body style="margin:0;padding:0;background:' + mist + ';">'
  + '<span style="display:none;max-height:0;overflow:hidden;">' + esc(preheader) + '</span>'
  + '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:' + mist + ';padding:32px 12px;"><tr><td align="center">'
  + '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background:#ffffff;border:1px solid ' + line + ';border-radius:16px;font-family:' + font + ';color:' + ink + ';">'
  + '<tr><td style="padding:28px 32px 0 32px;font-size:18px;font-weight:700;letter-spacing:-0.3px;">guyshore.com</td></tr>'
  + '<tr><td style="padding:24px 32px 32px 32px;">' + inner + '</td></tr>'
  + '<tr><td style="padding:20px 32px;border-top:1px solid ' + line + ';font-size:12px;line-height:18px;color:' + slate + ';">'
  + 'GuyShore · Av. Elias Garcia, 123-A, 1050-098 Lisboa, Portugal · <a href="mailto:business@guyshore.com" style="color:' + slate + ';">business@guyshore.com</a></td></tr>'
  + '</table></td></tr></table></body></html>';

const quote = '<div style="margin:20px 0;padding:16px 18px;background:' + mist + ';border-left:3px solid ' + ink + ';border-radius:4px;font-size:15px;line-height:23px;color:' + steel + ';">' + msgHtml + '</div>';
const button = (href, label) => '<a href="' + esc(href) + '" style="display:inline-block;background:' + ink + ';color:#ffffff;text-decoration:none;font-weight:600;font-size:14px;padding:12px 22px;border-radius:999px;">' + esc(label) + '</a>';

// To the team
const teamSubject = 'Blog: ' + (name || 'someone') + ' wrote about "' + (articleTitle || 'an article') + '"';
const row = (k, v) => '<tr><td style="padding:6px 12px 6px 0;font-size:13px;color:' + slate + ';white-space:nowrap;vertical-align:top;">' + k + '</td><td style="padding:6px 0;font-size:14px;color:' + ink + ';">' + v + '</td></tr>';
const teamHtml = shell('New message from ' + name + ' on the blog',
  '<p style="margin:0 0 6px 0;font-size:12px;letter-spacing:1.5px;text-transform:uppercase;color:' + slate + ';">New message from the blog</p>'
  + '<h1 style="margin:0;font-size:22px;line-height:28px;letter-spacing:-0.4px;">' + esc(name) + ' wants to talk</h1>'
  + quote
  + '<table role="presentation" cellpadding="0" cellspacing="0" style="margin:0 0 22px 0;">'
  + row('Name', esc(name))
  + row('Email', '<a href="mailto:' + esc(email) + '" style="color:' + ink + ';">' + esc(email) + '</a>')
  + row('Article', '<a href="' + esc(articleUrl) + '" style="color:' + ink + ';">' + esc(articleTitle || articleUrl) + '</a>')
  + row('Language', lang === 'pt' ? 'Portuguese' : 'English')
  + row('Button', position === 'end' ? 'End of the article' : 'Middle of the article')
  + row('New posts by email', newsletter ? '<strong>Yes, opted in</strong>' : 'No')
  + '</table>'
  + button('mailto:' + email + '?subject=' + encodeURIComponent('Re: ' + (articleTitle || 'guyshore.com')), 'Reply to ' + (name.split(' ')[0] || 'them'))
  + '<p style="margin:18px 0 0 0;font-size:12px;color:' + slate + ';">A copy went to ' + esc(email) + ' with business@ in cc. Replying to this email also reaches them.</p>');

// To the reader, in their language
const first = esc(name.split(' ')[0] || name);
const T = lang === 'pt'
  ? {
      subject: 'Recebemos a sua mensagem sobre "' + articleTitle + '"',
      pre: 'Respondemos no prazo de um dia útil.',
      eyebrow: 'Mensagem recebida',
      h1: 'Olá ' + first + ', obrigado por escrever.',
      p1: 'Recebemos a sua mensagem sobre o artigo <a href="' + esc(articleUrl) + '" style="color:' + ink + ';">' + esc(articleTitle) + '</a>. Quem escreveu o artigo lê todas as mensagens e responde no prazo de um dia útil, a partir de business@guyshore.com.',
      copy: 'A sua mensagem',
      p2: 'Se quiser acrescentar contexto, como ferramentas, prazos ou um exemplo, basta responder a este email.',
      news: '<p style="margin:16px 0 0 0;font-size:14px;line-height:22px;color:' + steel + ';">Também vai receber os novos artigos neste email. Para deixar de os receber, basta responder a este email.</p>',
      cta: 'Ver mais artigos', blog: 'https://guyshore.com/pt/blog',
    }
  : {
      subject: 'We got your message about "' + articleTitle + '"',
      pre: 'We reply within one working day.',
      eyebrow: 'Message received',
      h1: 'Hi ' + first + ', thanks for writing.',
      p1: 'We received your message about <a href="' + esc(articleUrl) + '" style="color:' + ink + ';">' + esc(articleTitle) + '</a>. The person who wrote the article reads every message and replies within one working day, from business@guyshore.com.',
      copy: 'Your message',
      p2: 'If you want to add context, such as tools, deadlines or an example, just reply to this email.',
      news: '<p style="margin:16px 0 0 0;font-size:14px;line-height:22px;color:' + steel + ';">You will also get new articles at this address. To stop them, just reply to this email.</p>',
      cta: 'Read more articles', blog: 'https://guyshore.com/blog',
    };

const readerHtml = shell(T.pre,
  '<p style="margin:0 0 6px 0;font-size:12px;letter-spacing:1.5px;text-transform:uppercase;color:' + slate + ';">' + T.eyebrow + '</p>'
  + '<h1 style="margin:0;font-size:22px;line-height:28px;letter-spacing:-0.4px;">' + T.h1 + '</h1>'
  + '<p style="margin:16px 0 0 0;font-size:15px;line-height:23px;color:' + steel + ';">' + T.p1 + '</p>'
  + '<p style="margin:22px 0 0 0;font-size:12px;letter-spacing:1.5px;text-transform:uppercase;color:' + slate + ';">' + T.copy + '</p>'
  + quote
  + '<p style="margin:0;font-size:15px;line-height:23px;color:' + steel + ';">' + T.p2 + '</p>'
  + (newsletter ? T.news : '')
  + '<p style="margin:24px 0 0 0;">' + button(T.blog, T.cta) + '</p>'
  + '<p style="margin:24px 0 0 0;font-size:15px;color:' + ink + ';">Guy Sartori<br><span style="color:' + slate + ';font-size:13px;">GuyShore</span></p>');

return [{ json: { valid, name, email, message, lang, articleTitle, articleUrl, newsletter, position,
  teamSubject, teamHtml, readerSubject: T.subject, readerHtml, submittedAt: str(b.submittedAt) || new Date().toISOString() } }];
